package com.tracker.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.*;
@Entity @Table(name="certifications") @Getter @Setter @NoArgsConstructor
public class Certification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=150) private String certificationName; @NotBlank @Size(max=150) private String issuingOrganization; @NotNull @PastOrPresent private LocalDate issueDate; private LocalDate expiryDate; @Size(max=100) private String credentialId; @Size(max=80) private String category; @Pattern(regexp="^$|^https?://\\S+$") private String credentialUrl; @Size(max=1000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private CertStatus status=CertStatus.PENDING; @Size(max=500) private String reviewRemarks; private LocalDateTime submittedAt; private LocalDateTime verifiedAt; @JsonIgnore private String evidenceFileName; @JsonIgnore private String evidenceContentType; @JsonIgnore private String evidenceStorageKey; @ManyToOne @JoinColumn(name="verifying_faculty_id") @JsonIgnore private User verifyingFaculty; private LocalDateTime createdAt; @ManyToOne(optional=false) @JoinColumn(name="user_id") @JsonIgnore private User user; @PrePersist void created(){createdAt=LocalDateTime.now();if(submittedAt==null)submittedAt=createdAt;} public Long getStudentId(){return user==null?null:user.getId();} public String getStudentName(){return user==null?null:user.getName();} public String getStudentEmail(){return user==null?null:user.getEmail();} }
